import unittest
from scr.invoice_handler.xml_pdf_extraction import get_pdf_file
from scr.helper_functions.einvoice_helper import read_xml_file_to_str


class TestXmlPDFExtraction(unittest.TestCase):
    def test_get_xml_pdf_extraction_all(self):
        m_cn_id = "123456"
        pdf_text_from_xml_file = read_xml_file_to_str('xml_files/xml_from_pdf_extraction.xml')
        file: list = get_pdf_file(m_cn_id, pdf_text_from_xml_file)
        self.assertEqual(file, [{'M_CN_ID': '123456',
                                 'ATTACHMENT': '',
                                 'FILE_NAME': '01_15_Anhang_01.pdf', 'FILE_TYPE': 'pdf'}]
                         )

    def test_get_pdf_from_sap(self):
        m_cn_id = "123456"
        pdf_text_from_xml_file = read_xml_file_to_str('xml_files/deliveryDateIsEmpty.xml')
        file: list = get_pdf_file(m_cn_id, pdf_text_from_xml_file)
        print("file ", file)

        self.assertEqual(file, [{'M_CN_ID': '123456',
                                 'ATTACHMENT': '',
                                 'FILE_NAME': '49096521.pdf', 'FILE_TYPE': 'pdf'}]
                         )

    def test_get_two_pdfs(self):
        m_cn_id = "7980166"
        pdf_text_from_xml_file = read_xml_file_to_str('xml_files/cc_budget_and_another.xml')
        file: list = get_pdf_file(m_cn_id, pdf_text_from_xml_file)
        self.assertEqual(file, [{'M_CN_ID': '7980166',
                                 'ATTACHMENT': '',
                                 'FILE_NAME': '24552_20483-1719690851-IMAGE-D.pdf', 'FILE_TYPE': 'pdf'},
                                {'M_CN_ID': '7980166',
                                 'ATTACHMENT': '',
                                 'FILE_NAME': 'ATTACHMENT-24552_20483-1719690851-9715df7da4c84fd4a6623593bb6a625b.pdf',
                                 'FILE_TYPE': 'pdf'}]
                         )

    def test_get_xml_pdf_sixthaddressed(self):
        m_cn_id = "123456"
        pdf_text_from_xml_file = read_xml_file_to_str('xml_files/sixt_adress.xml')
        file: list = get_pdf_file(m_cn_id, pdf_text_from_xml_file)
        self.assertEqual(file, [{'M_CN_ID': '123456',
                                 'ATTACHMENT': '',
                                 'FILE_NAME': '0419261_3567770.pdf', 'FILE_TYPE': 'pdf'}]
                         )

    def test_get_no_attachment(self):
        m_cn_id = "7980166"
        pdf_text_from_xml_file = read_xml_file_to_str('xml_files/xml_text_find_VIN_USTD_SWFM-5490.xml')
        file: list = get_pdf_file(m_cn_id, pdf_text_from_xml_file)
        self.assertEqual(file, [])
